def _early_valid(owner, now):
    return owner["scope"] == "PUBLISHER" and owner["expires_at"] > now()

def _publication_valid(owner, identity, now):
    publication_time = now()
    return (
        owner["scope"] == "PUBLISHER"
        and owner["expires_at"] > publication_time
        and (owner["owner_id"], owner["token"], owner["acquired_at"]) == identity
    )

def publish(value, owner, prepare, now, output):
    if not _early_valid(owner, now):
        return False
    identity = (owner["owner_id"], owner["token"], owner["acquired_at"])
    prepared = prepare(value)
    if not _publication_valid(owner, identity, now):
        return False
    output.append(prepared)
    return True

def merge(value, owner, prepare, now, output):
    if not _early_valid(owner, now):
        return False
    identity = (owner["owner_id"], owner["token"], owner["acquired_at"])
    prepared = prepare(value)
    if not _publication_valid(owner, identity, now):
        return False
    output.append({"merged": prepared})
    return True
